import pandas as pd
import numpy as np
import itertools
from datetime import datetime, timedelta
import seaborn as sns


def task_func(
    df,
    fruits=None,
    days=None,
    seed=None,
    sales_lower_bound=1,
    sales_upper_bound=50,
):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("'df' must be a pandas DataFrame")

    if not df.empty:
        raise ValueError("'df' must be empty")

    if sales_lower_bound >= sales_upper_bound:
        raise ValueError("'sales_lower_bound' must be less than 'sales_upper_bound'")

    if fruits is None:
        fruits = ["Apple", "Banana", "Orange"]

    if days is None:
        days = 7

    if isinstance(days, int):
        date_values = [
            datetime.now() + timedelta(days=offset)
            for offset in range(days)
        ]
    else:
        date_values = list(days)

    rng = np.random.default_rng(seed)
    combinations = list(itertools.product(date_values, fruits))
    sales = rng.integers(
        sales_lower_bound,
        sales_upper_bound,
        size=len(combinations),
    )

    generated_data = pd.DataFrame(
        [
            {
                "Date": date_value,
                "Fruit": fruit,
                "Sales": sale,
            }
            for (date_value, fruit), sale in zip(combinations, sales)
        ]
    )

    updated_df = pd.concat([df, generated_data], ignore_index=True)
    plot = sns.catplot(data=updated_df, x="Fruit", y="Sales", kind="box")

    return updated_df, plot

