import re
import json
import requests


def task_func(myString, token):
    """Extract the first URL from myString and submit it to the REST API."""
    match = re.search(r"https?://[^\s<>'\"]+", myString)
    if not match:
        raise ValueError("No URL found in the input string.")

    url = match.group(0).rstrip(".,!?;:)]}")

    api_endpoint = "https://api.example.com/submit"
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
    }
    payload = {"url": url}

    response = requests.post(
        api_endpoint,
        headers=headers,
        data=json.dumps(payload),
    )
    response.raise_for_status()
    return response.json()

