import re
import random


def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    products = ['Apple', 'Banana', 'Orange', 'Pear', 'Grape']
    rng = random.Random(seed)
    product_by_code = {}
    rows = []

    for line in s.splitlines():
        line = line.strip()
        if not line:
            continue

        parts = re.split(r'\s+', line, maxsplit=4)
        if len(parts) < 5:
            continue

        product_id, quantity, code, price, description = (
            part.rstrip() for part in parts
        )

        if code not in product_by_code:
            product_by_code[code] = rng.choice(products)

        rows.append({
            'ID': int(product_id),
            'Quantity': int(quantity),
            'Code': code,
            'Price': int(price),
            'Product': product_by_code[code],
            'Description': description.rstrip(),
        })

    return pd.DataFrame(
        rows,
        columns=['ID', 'Quantity', 'Code', 'Price', 'Product', 'Description']
    )

import subprocess
import os
import signal
import time


def task_func(process_name: str) -> int:
    current_pid = os.getpid()
    pids = []

    if os.name == "nt":
        try:
            result = subprocess.run(
                ["tasklist", "/FO", "CSV", "/NH"],
                capture_output=True,
                text=True,
                check=False,
            )
            target = process_name.lower()
            for line in result.stdout.splitlines():
                fields = line.strip().strip('"').split('","')
                if len(fields) >= 2 and fields[0].lower() == target:
                    try:
                        pid = int(fields[1])
                        if pid != current_pid:
                            pids.append(pid)
                    except ValueError:
                        continue
        except OSError:
            return 0
    else:
        try:
            result = subprocess.run(
                ["ps", "-eo", "pid=,comm="],
                capture_output=True,
                text=True,
                check=False,
            )
            target = os.path.basename(process_name)
            for line in result.stdout.splitlines():
                parts = line.strip().split(None, 1)
                if len(parts) == 2:
                    try:
                        pid = int(parts[0])
                    except ValueError:
                        continue
                    if pid != current_pid and parts[1] == target:
                        pids.append(pid)
        except OSError:
            return 0

    stopped = 0
    for pid in pids:
        try:
            os.kill(pid, signal.SIGTERM)
            stopped += 1
        except (ProcessLookupError, PermissionError, OSError):
            continue

    if stopped:
        time.sleep(1)

    return stopped

