def task_func(s, n):
    """Return up to n distinct English words found in s, ignoring case."""
    if n <= 0:
        return []

    found = {
        word.lower()
        for word in re.findall(r"[A-Za-z]+", s)
        if word.lower() in _ENGLISH_WORDS_LOWER
    }

    return sample(list(found), min(n, len(found)))

