import os
import shutil

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    os.makedirs(BACKUP_DIR, exist_ok=True)
    index = 1
    while True:
        backup_dir = os.path.join(BACKUP_DIR, f'backup_{index}')
        if not os.path.exists(backup_dir):
            return backup_dir
        index += 1


def task_func(directory):
    errors = []
    backup_dir = get_unique_backup_dir()

    try:
        if not os.path.isdir(directory):
            return backup_dir, [f"Directory does not exist: {directory}"]

        os.makedirs(backup_dir)

        for entry in os.listdir(directory):
            source = os.path.join(directory, entry)
            destination = os.path.join(backup_dir, entry)

            try:
                if os.path.isdir(source) and not os.path.islink(source):
                    shutil.copytree(source, destination)
                    shutil.rmtree(source)
                else:
                    shutil.copy2(source, destination)
                    os.remove(source)
            except (OSError, shutil.Error) as error:
                errors.append(f"{source}: {error}")

    except (OSError, shutil.Error) as error:
        errors.append(str(error))

    return backup_dir, errors

import subprocess
import os
import shutil
from glob import glob


def task_func(src_folder, dst_folder):
    """Compress all files in src_folder and move the .gz files to dst_folder."""
    source_files = [
        path for path in glob(os.path.join(src_folder, "*"))
        if os.path.isfile(path)
    ]

    if not source_files:
        return {
            "success": True,
            "message": "No files found to compress.",
            "failed_files": [],
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except OSError as exc:
        return {
            "success": False,
            "message": f"Failed to create destination folder: {exc}",
            "failed_files": [os.path.basename(path) for path in source_files],
        }

    processes = []
    failed_files = []

    for source_path in source_files:
        try:
            process = subprocess.Popen(
                ["gzip", "-f", source_path],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            processes.append((source_path, process))
        except (OSError, subprocess.SubprocessError):
            failed_files.append(os.path.basename(source_path))

    for source_path, process in processes:
        filename = os.path.basename(source_path)
        try:
            return_code = process.wait()
            if return_code != 0:
                failed_files.append(filename)
                continue

            compressed_path = source_path + ".gz"
            destination_path = os.path.join(
                dst_folder,
                os.path.basename(compressed_path),
            )
            shutil.move(compressed_path, destination_path)
        except (OSError, subprocess.SubprocessError):
            failed_files.append(filename)

    if failed_files:
        return {
            "success": False,
            "message": (
                f"Compression or moving failed for {len(failed_files)} file(s)."
            ),
            "failed_files": failed_files,
        }

    return {
        "success": True,
        "message": f"Successfully compressed and moved {len(source_files)} file(s).",
        "failed_files": [],
    }

