import numpy as np
import random

def task_func(MIN_WORDS, MAX_WORDS, WORDS_POOL):
    if MIN_WORDS < 1 or MAX_WORDS < MIN_WORDS:
        raise ValueError("Invalid word-count range.")
    if not WORDS_POOL:
        raise ValueError("WORDS_POOL must not be empty.")

    length = random.randint(MIN_WORDS, MAX_WORDS)
    first_half = [random.choice(WORDS_POOL) for _ in range(length // 2)]

    if length % 2:
        words = first_half + [random.choice(WORDS_POOL)] + first_half[::-1]
    else:
        words = first_half + first_half[::-1]

    return " ".join(words)

