import http.server
import json

SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}

ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}


class DataRequestHandler(http.server.BaseHTTPRequestHandler):
    def _send_json_response(self, status_code, response):
        body = json.dumps(response).encode('utf-8')
        self.send_response(status_code)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self):
        content_type = self.headers.get('Content-Type', '')
        media_type = content_type.split(';', 1)[0].strip().lower()

        if media_type != 'application/json':
            self._send_json_response(400, {
                'status': 'error',
                'message': 'Content-Type header is not application/json'
            })
            return

        try:
            content_length = int(self.headers.get('Content-Length', 0))
            body = self.rfile.read(content_length)
            request_data = json.loads(body)
        except (ValueError, TypeError, json.JSONDecodeError, UnicodeDecodeError):
            self._send_json_response(400, {
                'status': 'error',
                'message': 'Invalid JSON'
            })
            return

        if not isinstance(request_data, dict) or 'data' not in request_data:
            self._send_json_response(400, {
                'status': 'error',
                'message': 'No data key in request'
            })
            return

        self._send_json_response(200, SUCCESS_RESPONSE)


def task_func():
    return DataRequestHandler

