import subprocess
import time
import json
import platform

LOGFILE_PATH = "logfile.log"


def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    records = []
    start_time = time.time()

    while time.time() - start_time < duration:
        if platform.system() == "Windows":
            output = subprocess.check_output(
                "wmic cpu get loadpercentage",
                shell=True
            ).decode(errors="replace")

            values = [
                line.strip()
                for line in output.splitlines()
                if line.strip().isdigit()
            ]
            cpu_usage = float(values[0]) if values else 0.0
        else:
            output = subprocess.check_output(
                "top -bn1 | grep 'Cpu(s)'",
                shell=True
            ).decode(errors="replace")

            cpu_usage = 0.0
            parts = output.replace(",", " ").split()
            for index, part in enumerate(parts):
                if part.lower().startswith("id") and index > 0:
                    idle = float(parts[index - 1].replace("%", ""))
                    cpu_usage = 100.0 - idle
                    break

        records.append({
            "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
            "cpu_usage": cpu_usage
        })

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as logfile:
            json.dump(records, logfile, indent=4)
    except IOError:
        return None

    return LOGFILE_PATH

