def task_func(json_data: str, key_path: list):
    if not isinstance(json_data, str) or not json_data.strip():
        raise ValueError("JSON data is empty or invalid.")

    try:
        data = json.loads(json_data)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError("JSON data is corrupted.") from exc

    current = data
    for key in key_path:
        if not isinstance(current, dict) or key not in current:
            raise KeyError(key)
        current = current[key]

    values = []

    def collect_numbers(item):
        if isinstance(item, bool):
            return
        if isinstance(item, (int, float)):
            if np.isfinite(item):
                values.append(item)
        elif isinstance(item, dict):
            for value in item.values():
                collect_numbers(value)
        elif isinstance(item, (list, tuple)):
            for value in item:
                collect_numbers(value)

    collect_numbers(current)

    if not values:
        raise ValueError("No numeric data found.")

    frame = pd.DataFrame({"value": values})
    figure, axis = plt.subplots()
    sns.boxplot(data=frame, y="value", ax=axis)
