import os
import re
import hashlib


def task_func(path, delimiter):
    if not isinstance(path, str) or not isinstance(delimiter, str):
        raise TypeError("path and delimiter must be strings")

    if delimiter == "":
        components = [path]
    else:
        parts = re.split(f"({re.escape(delimiter)})", path)
        components = []
        current = ""

        for part in parts:
            current += part
            if part == delimiter:
                components.append(current)
                current = ""

        if current:
            components.append(current)

    result = []
    for component in components:
        file_hash = None
        if os.path.isfile(component):
            digest = hashlib.sha256()
            with open(component, "rb") as file:
                for chunk in iter(lambda: file.read(8192), b""):
                    digest.update(chunk)
            file_hash = digest.hexdigest()

        result.append((component, file_hash))

    return result

