        scipy.fft.fft(np.array(repeated_data))

    return {
        "mode": modes,
        "count": np.full(len(modes), max_count, dtype=int),
    }

import numpy as np
import pandas as pd


def task_func(
    products,
    n_samples=100,
    sales_lower=50,
    sales_upper=200,
    profit_margin_min=0.1,
    profit_margin_max=0.5,
    random_seed=42,
):
    if not isinstance(products, list) or not all(
        isinstance(product, str) for product in products
    ):
        raise TypeError("products must be a list of strings")

    if (
        not isinstance(sales_lower, (int, float, np.number))
        or isinstance(sales_lower, bool)
        or not isinstance(sales_upper, (int, float, np.number))
        or isinstance(sales_upper, bool)
        or not isinstance(profit_margin_min, (int, float, np.number))
        or isinstance(profit_margin_min, bool)
        or not isinstance(profit_margin_max, (int, float, np.number))
        or isinstance(profit_margin_max, bool)
    ):
        raise TypeError("Sales and profit margin bounds must be numeric")

    if not isinstance(n_samples, (int, np.integer)) or isinstance(n_samples, bool):
        raise ValueError("n_samples must be a positive integer")

    if n_samples <= 0:
        raise ValueError("n_samples must be a positive integer")

    if sales_lower > sales_upper:
        raise ValueError("sales_lower must not be greater than sales_upper")

    if not products:
        return pd.DataFrame(columns=["Product", "Sales", "Profit"])

    rng = np.random.default_rng(random_seed)

    sampled_products = rng.choice(products, size=n_samples)
    sales = rng.uniform(sales_lower, sales_upper, size=n_samples)
    profit_margins = rng.uniform(
        profit_margin_min, profit_margin_max, size=n_samples
    )
    profit = sales * profit_margins

    data = pd.DataFrame(
        {
            "Product": sampled_products,
            "Sales": sales,
            "Profit": profit,
        }
    )

    return (
        data.groupby("Product", as_index=False)[["Sales", "Profit"]]
        .sum()
        .sort_values("Profit", ascending=False)
        .reset_index(drop=True)
    )

