            ]
        else:
            midpoints = (unique_values[:-1] + unique_values[1:]) / 2
            bins = np.concatenate([
                [unique_values[0] - 0.5],
                midpoints,
                [unique_values[-1] + 0.5],
            ])
    else:
        values = np.array([], dtype=int)
        bins = 1

    return pd.Series(values).hist(bins=bins, rwidth=0.8)

