def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        if isinstance(json_data, (str, bytes, bytearray)):
            data = json.loads(json_data)
        else:
            data = json_data
    except (json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ValueError("Malformed JSON data") from exc

    if not data:
        raise ValueError("JSON data cannot be empty")

    if isinstance(data, dict):
        records = list(data.items())
    elif isinstance(data, list):
        records = []
        for item in data:
            if not isinstance(item, dict):
                raise ValueError("Invalid population record")
            if "Country" not in item or "Population" not in item:
                raise ValueError("Invalid population record")
            records.append((item["Country"], item["Population"]))
    else:
        raise ValueError("JSON data must contain country-population records")

    normalized = []
    for country, population in records:
        if not isinstance(country, str):
            raise ValueError("Country names must be strings")
        if (
            isinstance(population, bool)
            or not isinstance(population, (int, float))
            or not math.isfinite(population)
            or population < 0
        ):
            raise ValueError("Populations must be non-negative numbers")

        normalized.append(
            {"Country": country, "Population": math.floor(population)}
        )

    if not normalized:
        raise ValueError("JSON data cannot be empty")

    dataframe = pd.DataFrame(normalized, columns=["Country", "Population"])
    output_path = os.path.join(output_dir, file_name)

    try:
        if output_dir:
            os.makedirs(output_dir, exist_ok=True)
        dataframe.to_csv(output_path, index=False)
