from datetime import datetime


def task_func(log_file):
    pattern = re.compile(r"^\s*([^:\s]+):\s*\[([^\]]+)\]\s*-\s*(.*)\s*$")
    entries = []

    with open(log_file, "r", encoding="utf-8") as file:
        for line in file:
            match = pattern.match(line.rstrip("\r\n"))
            if not match:
                continue

            log_type, timestamp_text, message = match.groups()

            try:
                timestamp = datetime.strptime(
                    timestamp_text, "%Y-%m-%d %H:%M:%S"
                )
            except ValueError as exc:
                raise ValueError(
                    f"Invalid timestamp: {timestamp_text}"
                ) from exc

            entries.append(
                {
                    "Type": log_type,
                    "Timestamp": timestamp.strftime("%Y-%m-%d %H:%M:%S"),
                    "Message": message,
                }
            )

    if not entries:
        raise ValueError("No valid log entries found")

    output_file = re.sub(r"\.[^.\\\/]+$", ".csv", log_file)
    if output_file == log_file:
        output_file = f"{log_file}.csv"

    pd.DataFrame(entries, columns=["Type", "Timestamp", "Message"]).to_csv(
        output_file, index=False
    )

    return output_file

