def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    if not os.path.isdir(directory):
        raise OSError(f"Directory does not exist: {directory}")

    counts = Counter({extension: 0 for extension in extensions})

    for path in glob.glob(os.path.join(directory, "**", "*"), recursive=True):
        if os.path.isfile(path):
            extension = os.path.splitext(path)[1]
            if extension in counts:
                counts[extension] += 1

    if not keep_zero:
        counts += Counter()

