from datetime import datetime, timezone


def task_func(directory_path: str):
    directory = Path(directory_path)

    if not directory.exists():
        raise ValueError(f"Directory does not exist: {directory_path}")

    result = []

    for file_path in directory.iterdir():
        if file_path.is_file():
            stat = file_path.stat()
            creation_time = datetime.fromtimestamp(
                stat.st_ctime, tz=timezone.utc
            ).isoformat()
            modification_time = datetime.fromtimestamp(
                stat.st_mtime, tz=timezone.utc
            ).isoformat()

            result.append(
                (
                    file_path.name,
                    stat.st_size,
                    creation_time,
                    modification_time,
                )
            )

    return result

import os
import glob
import zipfile


def task_func(directory):
    if not os.path.isdir(directory):
        raise FileNotFoundError(directory)

    zip_path = os.path.join(directory, "files.zip")
    files = [
        path
        for path in glob.glob(os.path.join(directory, "*"))
        if os.path.isfile(path) and os.path.abspath(path) != os.path.abspath(zip_path)
    ]

    if not files:
        return None

    with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as archive:
        for file_path in files:
            archive.write(file_path, arcname=os.path.basename(file_path))

    return zip_path

import json
import re
from collections import Counter

# Constants
REPLACE_NONE = "None"


def task_func(json_str):
    data = json.loads(json_str)
    email_pattern = re.compile(r"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b")

    def process(value):
        if value is None:
            return None
        if isinstance(value, dict):
            return {
                key: processed
                for key, item in value.items()
                if item is not None
                for processed in [process(item)]
            }
        if isinstance(value, list):
            return [processed for item in value if item is not None for processed in [process(item)]]
        if isinstance(value, str):
            return email_pattern.sub(REPLACE_NONE, value)
        return value

    processed_data = process(data)
    value_counts = Counter()

    def count_values(value):
        if isinstance(value, dict):
            for item in value.values():
                count_values(item)
        elif isinstance(value, list):
            for item in value:
                count_values(item)
        else:
            value_counts[value] += 1

    count_values(processed_data)

    return {
        "data": processed_data,
        "value_counts": value_counts,
    }

