import math

def task_func(x, w):
    if not x:
        return ""

    prefix = [0]
    for char in x:
        prefix.append(prefix[-1] + w[char])

    max_weight = -math.inf
    max_substr = ""

    for start, end in combinations(range(len(x) + 1), 2):
        weight = prefix[end] - prefix[start]
        if weight > max_weight:
            max_weight = weight
            max_substr = x[start:end]

    return max_substr

