import pandas as pd
import re

# Function to replace acronyms in DataFrame
def task_func(data, mapping):
    result = data.copy()

    if not mapping:
        return result

    acronyms = [key for key in mapping if isinstance(key, str) and key]
    if not acronyms:
        return result

    pattern = re.compile(
        r"(?<!\w)(?:" + "|".join(map(re.escape, sorted(acronyms, key=len, reverse=True))) + r")(?!\w)"
    )

    def replace_cell(value):
        if isinstance(value, str):
            return pattern.sub(lambda match: str(mapping[match.group(0)]), value)
        return value

    return result.apply(lambda column: column.map(replace_cell))

