import pandas as pd
import matplotlib.pyplot as plt
from statsmodels.tsa.seasonal import seasonal_decompose, freq_to_period


def task_func(df, freq='D', decomposition_model='multiplicative'):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("'df' must be a pandas DataFrame")

    if 'value' not in df.columns:
        raise ValueError("DataFrame must contain a 'value' column")

    if not pd.api.types.is_numeric_dtype(df['value']) or pd.api.types.is_bool_dtype(
        df['value']
    ):
        raise ValueError("'value' must contain numeric data")

    if df['value'].isna().any() or not df['value'].map(pd.api.types.is_number).all():
        raise ValueError("'value' contains invalid data")

    if not isinstance(freq, str):
        raise ValueError("'freq' must be a valid frequency string")

    try:
        pd.tseries.frequencies.to_offset(freq)
        period = freq_to_period(freq)
    except (TypeError, ValueError):
        raise ValueError("'freq' must be a valid frequency string")

    if decomposition_model not in ('additive', 'multiplicative'):
        raise ValueError(
            "'decomposition_model' must be 'additive' or 'multiplicative'"
        )

    values = df['value'].astype(float)

    if decomposition_model == 'multiplicative' and (values <= 0).any():
        raise ValueError("Multiplicative decomposition requires positive values")

    try:
        decomposition = seasonal_decompose(
            values,
            model=decomposition_model,
            period=period,
        )
    except Exception as exc:
        raise ValueError("Unable to decompose the time series") from exc

    fig, ax = plt.subplots()
    ax.plot(values.index, decomposition.observed, label='Observed')
    ax.plot(values.index, decomposition.trend, label='Trend')
    ax.plot(values.index, decomposition.seasonal, label='Seasonal')
    ax.plot(values.index, decomposition.resid, label='Residual')
    ax.set_title('Time Series Decomposition')
    ax.legend()

    return decomposition, ax

