from datetime import datetime
import pytz
import numpy as np


def task_func(time_strings, timezone):
    if len(time_strings) < 2:
        return 0.0

    target_timezone = (
        pytz.timezone(timezone) if isinstance(timezone, str) else timezone
    )

    timestamps = []
    for time_string in time_strings:
        timestamp = datetime.fromisoformat(time_string.replace("Z", "+00:00"))
        if timestamp.tzinfo is None:
            timestamp = target_timezone.localize(timestamp)
        else:
            timestamp = timestamp.astimezone(target_timezone)
        timestamps.append(timestamp)

    differences = [
        abs((timestamps[index + 1] - timestamps[index]).total_seconds())
        for index in range(len(timestamps) - 1)
    ]

    return float(np.mean(differences)) if differences else 0.0

