import re
from pathlib import Path


def task_func(dir_path: str, predicates: list) -> dict:
    directory = Path(dir_path)
    if not directory.is_dir():
        raise FileNotFoundError(f"Directory does not exist: {dir_path}")

    valid_predicates = []
    seen = set()

    for predicate in predicates:
        if not isinstance(predicate, str):
            continue

        try:
            re.compile(predicate)
        except re.error:
            continue

        if predicate not in seen:
            seen.add(predicate)
            valid_predicates.append(predicate)

    if not valid_predicates:
        raise ValueError("No valid predicates were provided")

    return {
        item.name: [
            re.search(predicate, item.name) is not None
            for predicate in valid_predicates
        ]
        for item in directory.iterdir()
    }

import os
import shutil

def task_func(src_dir, dest_dir, extension):
    os.makedirs(dest_dir, exist_ok=True)
    files_moved = 0

    for filename in os.listdir(src_dir):
        source_path = os.path.join(src_dir, filename)

        if os.path.isfile(source_path) and filename.endswith(extension):
            shutil.move(source_path, os.path.join(dest_dir, filename))
            files_moved += 1

    return {"files_moved": files_moved}

import random
import re

def task_func(target_words, n_sentences, vocabulary):
    if n_sentences < 0 or not vocabulary:
        raise ValueError

    patterns = [
        re.compile(r"(?<!\w)" + re.escape(word.lower()) + r"(?!\w)")
        for word in target_words
        if word
    ]

    sentences = []
    for _ in range(n_sentences):
        sentence = " ".join(random.choices(vocabulary, k=10)).lower()
        for pattern in patterns:
            sentence = pattern.sub(
                lambda match: match.group(0).replace(" ", "_"),
                sentence,
            )
        sentences.append(sentence)

    return sentences

