import pandas as pd
from datetime import datetime
import random


def task_func(
    epoch_milliseconds,
    random_seed=0,
    products=["Product1", "Product2", "Product3", "Product4", "Product5"],
):
    if isinstance(epoch_milliseconds, bool) or not isinstance(
        epoch_milliseconds, (int, float)
    ):
        raise TypeError("epoch_milliseconds must be a number")

    if len(products) != 5 or not all(isinstance(product, str) for product in products):
        raise ValueError("products must contain exactly five strings")

    current_datetime = datetime.now()

    try:
        start_datetime = datetime.fromtimestamp(epoch_milliseconds / 1000)
    except (OverflowError, OSError, ValueError) as exc:
        raise ValueError("Invalid epoch_milliseconds") from exc

    if start_datetime > current_datetime:
        raise ValueError("epoch_milliseconds cannot be in the future")

    dates = pd.date_range(
        start=start_datetime.date(),
        end=current_datetime.date(),
        freq="D",
    )

    generator = random.Random(random_seed)
    rows = []

    for date in dates:
        for product in products:
            rows.append(
                {
                    "Product": product,
                    "Date": date.to_pydatetime(),
                    "Sales": generator.randint(10, 50),
                }
            )

    return pd.DataFrame(rows, columns=["Product", "Date", "Sales"])

