import socket
import select
import queue
from datetime import datetime, timedelta


def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    clients = {}
    outgoing = {}
    pending = {}

    try:
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((server_address, server_port))
        server_socket.listen()
        server_socket.setblocking(False)

        start_time = datetime.now()
        deadline = start_time + timedelta(seconds=run_duration)

        while datetime.now() < deadline:
            remaining = max(0.0, (deadline - datetime.now()).total_seconds())
            read_sockets = [server_socket, *clients]
            write_sockets = [
                client
                for client in clients
                if client in pending or not outgoing[client].empty()
            ]
            exceptional_sockets = [server_socket, *clients]

            try:
                readable, writable, exceptional = select.select(
                    read_sockets,
                    write_sockets,
                    exceptional_sockets,
                    remaining,
                )
            except (OSError, ValueError):
                break

            if server_socket in exceptional:
                break

            if server_socket in readable:
                try:
                    client_socket, _ = server_socket.accept()
                    client_socket.setblocking(False)
                    clients[client_socket] = True
                    outgoing[client_socket] = queue.Queue()
                except OSError:
                    pass

            for client_socket in list(clients):
                if client_socket in exceptional:
                    try:
                        client_socket.close()
                    except OSError:
                        pass
                    clients.pop(client_socket, None)
                    outgoing.pop(client_socket, None)
                    pending.pop(client_socket, None)
                    continue

                if client_socket in readable:
                    try:
                        data = client_socket.recv(buffer_size)
                        if not data:
                            raise ConnectionError
                        response = data + str(datetime.now()).encode("utf-8")
                        outgoing[client_socket].put(response)
                    except (OSError, ConnectionError):
                        try:
                            client_socket.close()
                        except OSError:
                            pass
                        clients.pop(client_socket, None)
                        outgoing.pop(client_socket, None)
                        pending.pop(client_socket, None)

            for client_socket in writable:
                if client_socket not in clients:
                    continue

                try:
                    if client_socket not in pending:
                        pending[client_socket] = outgoing[client_socket].get_nowait()

                    sent = client_socket.send(pending[client_socket])
                    pending[client_socket] = pending[client_socket][sent:]

                    if not pending[client_socket]:
                        pending.pop(client_socket, None)
                except queue.Empty:
                    pass
                except (OSError, ConnectionError):
                    try:
                        client_socket.close()
                    except OSError:
                        pass
                    clients.pop(client_socket, None)
                    outgoing.pop(client_socket, None)
                    pending.pop(client_socket, None)
    finally:
        for client_socket in list(clients):
            try:
                client_socket.close()
            except OSError:
                pass
        try:
            server_socket.close()
        except OSError:
            pass

    return f"Echo server ran for {run_duration} seconds."

