def task_func(N=100, CATEGORIES=["A", "B", "C", "D", "E"], seed=42):
    rng = np.random.default_rng(seed)

    x = rng.random(N)
    y = rng.random(N)
    categories = list(CATEGORIES)

    if N < len(categories):
        selected_categories = rng.choice(categories, size=N, replace=False)
    else:
        selected_categories = np.array(categories, dtype=object)
        if N > len(categories):
            selected_categories = np.concatenate(
                [
                    selected_categories,
                    rng.choice(categories, size=N - len(categories), replace=True),
                ]
            )
        rng.shuffle(selected_categories)

    df = pd.DataFrame(
        {
            "x": x,
            "y": y,
            "category": selected_categories,
        }
    )

    fig, ax = plt.subplots()
    for category in categories:
        subset = df[df["category"] == category]
        if not subset.empty:
            ax.scatter(
                subset["x"],
                subset["y"],
                label=category,
            )

    if not df.empty:
        ax.legend()

    ax.set_xlabel("x")
    ax.set_ylabel("y")
