import warnings
import os
import glob
import shutil
import time


def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    transferred_files = []

    if not os.path.isdir(SOURCE_DIR):
        warnings.warn(f"Source directory does not exist: {SOURCE_DIR}")
        return transferred_files

    try:
        os.makedirs(DEST_DIR, exist_ok=True)
    except OSError as error:
        warnings.warn(f"Could not create destination directory: {error}")
        return transferred_files

    if isinstance(EXTENSIONS, str):
        EXTENSIONS = [EXTENSIONS]

    extensions = {
        str(extension).lower()
        if str(extension).startswith(".")
        else f".{str(extension).lower()}"
        for extension in EXTENSIONS
    }

    for file_path in glob.glob(os.path.join(SOURCE_DIR, "*")):
        if not os.path.isfile(file_path):
            continue

        if os.path.splitext(file_path)[1].lower() not in extensions:
            continue

        file_name = os.path.basename(file_path)
        destination_path = os.path.join(DEST_DIR, file_name)

        try:
            shutil.copy2(file_path, destination_path)
            transferred_files.append(file_name)
        except (OSError, shutil.Error) as error:
            warnings.warn(f"Could not transfer {file_name}: {error}")

    return transferred_files

