import re
import pandas as pd


def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    if pattern == "":
        return df.copy()

    regex = re.compile(pattern)

    def reverse_matching_words(value):
        if not isinstance(value, str):
            return value

        words = value.split()
        matching_words = [word for word in words if regex.match(word)]
        reversed_matching_words = iter(reversed(matching_words))

        return " ".join(
            next(reversed_matching_words) if regex.match(word) else word
            for word in words
        )

    result = df.copy()
    result[column_name] = result[column_name].apply(reverse_matching_words)
    return result

