import json
import os
import re


def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str},
        },
        "required": ["name", "age", "email"],
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$",
):
    if not os.path.isfile(file_path):
        raise ValueError(f"File does not exist: {file_path}")

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            data = json.load(file)
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError("Unable to read valid JSON from the file") from exc

    if INPUT_JSON.get("type") == "object" and not isinstance(data, dict):
        raise ValueError("JSON content must be an object")

    properties = INPUT_JSON.get("properties", {})
    required = INPUT_JSON.get("required", [])

    for field in required:
        if field not in data:
            raise ValueError(f"Missing required attribute: {field}")

    for field, rule in properties.items():
        if field not in data:
            continue

        expected_type = rule.get("type")
        value = data[field]

        if expected_type is not None and type(value) is not expected_type:
            raise ValueError(
                f"Attribute '{field}' must be of type "
                f"{expected_type.__name__}"
            )

    if "email" in data:
        email = data["email"]
        if not re.fullmatch(EMAIL_REGEX, email):
            raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute not found: {attribute}")

    if attribute in properties:
        expected_type = properties[attribute].get("type")
        if expected_type is not None and type(data[attribute]) is not expected_type:
            raise ValueError(
                f"Attribute '{attribute}' must be of type "
                f"{expected_type.__name__}"
            )

    return data[attribute]

