        soup = BeautifulSoup(response.text, "html.parser")
        table = soup.find("table")
        if table is None:
            raise ValueError("No table found on the page")

        rows = table.find_all("tr")
        headers = []
        data = []

        for row in rows:
            header_cells = row.find_all("th")
            data_cells = row.find_all("td")

            if header_cells and not headers:
                headers = [cell.get_text(strip=True) for cell in header_cells]

            if data_cells:
                data.append([cell.get_text(strip=True) for cell in data_cells])

        if not data:
            raise ValueError("No table data found on the page")

        if headers:
            if any(len(row) != len(headers) for row in data):
                raise ValueError("Table data does not match the header structure")
            return pd.DataFrame(data, columns=headers)

        return pd.DataFrame(data)

    except ValueError:
        raise
    except Exception as exc:
        raise ValueError("Page content could not be parsed") from exc

import pandas as pd
import folium
from geopy.geocoders import Photon


def task_func(dic):
    geolocator = Photon(user_agent="geoapiExercises")
    locations = []

    if isinstance(dic, dict):
        items = dic.items()
    else:
        items = enumerate(dic)

    for name, value in items:
        latitude = longitude = None

        if isinstance(value, dict):
            latitude = value.get("latitude", value.get("lat"))
            longitude = value.get("longitude", value.get("lon", value.get("lng")))
        elif isinstance(value, (list, tuple)) and len(value) >= 2:
            latitude, longitude = value[0], value[1]
        elif isinstance(value, str):
            parts = [part.strip() for part in value.split(",")]
            if len(parts) == 2:
                try:
                    latitude, longitude = float(parts[0]), float(parts[1])
                except ValueError:
                    pass

            if latitude is None:
                try:
                    result = geolocator.geocode(value)
                    if result is not None:
                        latitude, longitude = result.latitude, result.longitude
                except Exception:
                    pass

        if latitude is None or longitude is None:
            continue

        try:
            latitude, longitude = float(latitude), float(longitude)
        except (TypeError, ValueError):
            continue

        locations.append((name, latitude, longitude))

    if locations:
        center = [
            sum(latitude for _, latitude, _ in locations) / len(locations),
            sum(longitude for _, _, longitude in locations) / len(locations),
        ]
    else:
        center = [0, 0]

    map_object = folium.Map(location=center, zoom_start=2)

    for name, latitude, longitude in locations:
        folium.Marker(
            location=[latitude, longitude],
            popup=str(name),
            tooltip=str(name),
        ).add_to(map_object)

    return map_object

