import pandas as pd
from datetime import datetime
import matplotlib.pyplot as plt

# Constants
ROOMS = ["Room1", "Room2", "Room3", "Room4", "Room5"]


def task_func(date_str, booking_data):
    """Generate a room-booking status report and bar plot for a date."""
    try:
        if (
            not isinstance(date_str, str)
            or len(date_str) != 10
            or date_str[4] != "-"
            or date_str[7] != "-"
        ):
            raise ValueError
        requested_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except (TypeError, ValueError):
        raise ValueError("date_str must be a valid date in yyyy-mm-dd format")

    if requested_date < datetime.now().date():
        raise ValueError("date_str must not refer to a past date")

    def normalize_date(value):
        if hasattr(value, "date"):
            value = value.date()
        if hasattr(value, "isoformat"):
            return value.isoformat()
        return str(value)

    def status_from_value(value):
        if isinstance(value, bool):
            return "Booked" if value else "Available"
        if value is None:
            return "Available"
        if isinstance(value, str):
            lowered = value.strip().lower()
            if lowered in {"available", "free", "unbooked", "vacant"}:
                return "Available"
            if lowered in {"booked", "reserved", "occupied", "unavailable"}:
                return "Booked"
            return value
        return "Booked"

    def record_status(record, room):
        if not isinstance(record, dict):
            return None

        record_room = record.get("room", record.get("Room"))
        record_date = record.get("date", record.get("Date"))
        if record_room != room or normalize_date(record_date) != date_str:
            return None

        return status_from_value(
            record.get("status", record.get("Status", "Booked"))
        )

    def room_status(room):
        if isinstance(booking_data, pd.DataFrame):
            for _, record in booking_data.iterrows():
                result = record_status(record.to_dict(), room)
                if result is not None:
                    return result
            return "Available"

        if isinstance(booking_data, (list, tuple)):
            for record in booking_data:
                result = record_status(record, room)
                if result is not None:
                    return result
            return "Available"

        if not isinstance(booking_data, dict):
            return "Available"

        if date_str in booking_data:
            dated_data = booking_data[date_str]
            if isinstance(dated_data, dict) and room in dated_data:
                return status_from_value(dated_data[room])

        if room not in booking_data:
            return "Available"

        value = booking_data[room]

        if isinstance(value, dict):
            for key, item in value.items():
                if normalize_date(key) == date_str:
                    return status_from_value(item)

            if any(
                key.lower() in {"status", "booked", "reserved"}
                for key in value
                if isinstance(key, str)
            ):
                return status_from_value(
                    value.get("status", value.get("booked", value.get("reserved")))
                )
            return "Available"

        if isinstance(value, (list, tuple, set)):
            for item in value:
                if isinstance(item, dict):
                    result = record_status(
                        {"room": room, **item}, room
                    )
                    if result is not None:
                        return result
                elif normalize_date(item) == date_str:
                    return "Booked"
            return "Available"

        return status_from_value(value)

    statuses = [room_status(room) for room in ROOMS]
    report = pd.DataFrame({"Room": ROOMS, "Status": statuses})

    status_codes = {
        status: index
        for index, status in enumerate(dict.fromkeys(statuses), start=1)
    }
    values = [status_codes[status] for status in statuses]

    _, ax = plt.subplots()
    ax.bar(report["Room"], values)
    ax.set_xlabel("Room")
    ax.set_ylabel("Booking status")
    ax.set_title(f"Room booking status for {date_str}")
    ax.set_xticks(range(len(ROOMS)))
    ax.set_xticklabels(ROOMS)
    ax.set_yticks(list(status_codes.values()))
    ax.set_yticklabels(list(status_codes.keys()))

    return report, ax

