import pandas as pd
from scipy.stats import pearsonr


def task_func(data):
    if len(data) < 2:
        return float("nan")

    score_column = next(
        (column for column in ("score", "scores", "numerical_score") if column in data.columns),
        data.columns[0],
    )
    grade_column = next(
        (column for column in ("grade", "grades", "categorical_grade") if column in data.columns),
        data.columns[1],
    )

    scores = pd.to_numeric(data[score_column], errors="coerce")
    grades = data[grade_column]

    if pd.api.types.is_categorical_dtype(grades.dtype) and grades.cat.ordered:
        encoded_grades = pd.Series(grades.cat.codes, index=grades.index, dtype=float)
        encoded_grades[encoded_grades < 0] = float("nan")
    else:
        grade_values = grades.astype("string").str.strip().str.upper()
        common_order = ["A+", "A", "A-", "B+", "B", "B-", "C+", "C", "C-", "D+", "D", "D-", "F"]
        present = set(grade_values.dropna())
        if present and present.issubset(set(common_order)):
            ordering = [grade for grade in common_order if grade in present]
        else:
            ordering = sorted(present)

        mapping = {grade: len(ordering) - index - 1 for index, grade in enumerate(ordering)}
        encoded_grades = grade_values.map(mapping).astype(float)

    valid = scores.notna() & encoded_grades.notna()
    if valid.sum() < 2:
        return float("nan")

    correlation, _ = pearsonr(scores[valid], encoded_grades[valid])
    return float(correlation)

